func ByToTransitionsCount(opts ...sql.OrderTermOption) OrderOption {
	return func(s *sql.Selector) {
		sqlgraph.OrderByNeighborsCount(s, newToTransitionsStep(), opts...)
	}
}

// ByToTransitions orders the results by to_transitions terms.
func ByToTransitions(term sql.OrderTerm, terms ...sql.OrderTerm) OrderOption {
	return func(s *sql.Selector) {
		sqlgraph.OrderByNeighborTerms(s, newToTransitionsStep(), append([]sql.OrderTerm{term}, terms...)...)
	}
}
